const checkDomainSSOEnforcement = `-- name: CheckDomainSSOEnforcement :one
SELECT
  EXISTS (
    SELECT
      1
    FROM
      workspace_domains wd
      LEFT JOIN oidc_providers op ON op.workspace_id = wd.workspace_id
      AND op.is_active = TRUE
      LEFT JOIN saml_providers sp ON sp.workspace_id = wd.workspace_id
      AND sp.is_active = TRUE
    WHERE
      wd.domain = $1
      AND wd.verified_at IS NOT NULL
      AND (
        (
          op.workspace_id IS NOT NULL
          AND op.enforce_sso = TRUE
        )
        OR (
          sp.workspace_id IS NOT NULL
          AND sp.enforce_sso = TRUE
        )
      )
  )::BOOLEAN AS enforce_sso
`

func (q *Queries) CheckDomainSSOEnforcement(ctx context.Context, domain string) (bool, error) {
	row := q.db.QueryRow(ctx, checkDomainSSOEnforcement, domain)
	var enforce_sso bool
	err := row.Scan(&enforce_sso)
	return enforce_sso, err
}

